class METProcMetrics
{
    UtcDateTime                      dateTimeBegin;
    UtcDateTime                      lastDbWrite;
    NotesLine                        description[12];
    int                              descriptionCount[12];      
    real                             descriptionTimeStart[12];  
    real                             descriptionTotalTime[12];  
    real                             dualWriteTimeStart[12];
    real                             totalDualWrite[12];
    Integer                          lineCount, documentCount;
    Integer                          updateIntervalSec;
    RefRecId                         batchJobId;
    RefRecId                         logRecId;
    METBatchMonitoringLogParameters  logParams;
    METBatchMonitoringLog            log;
    Total                            totalCount;
    boolean                          currentLogNotFound;
    boolean                          isTraceEnded;

}

Method.Source:
public METBatchMonitoringLogParameters parmLogParams(METBatchMonitoringLogParameters _logParams = logParams)
{
    logParams = _logParams;
    return logParams;
}

public void startDescriptionTime(int _slot, NotesLine _label = '')
{
    if (_label)
    {
        description[_slot] = _label;
    }

    descriptionTimeStart[_slot] = System.DateTime::UtcNow.Ticks;
}

public void startTrace(Total _totalCount, NotesLine _description)
{
    totalCount   = _totalCount;
    description[1] = _description;
    this.beginTrace();
}

public void startTraceFromQuery(QueryRun _queryRun, NotesLine _description)
{
    totalCount   = QueryRun::getQueryRowCount(_queryRun.query(), intMax());
    description[1] = _description;
    this.beginTrace();
}

public METProcMetrics beginTrace(str _description = '', NoYes _isHeader = NoYes::No)
{
    UserConnection  userConnection;
    boolean         isCommitSuccessful;

    if (_description)
    {
        description[1] = _description;
    }

    if (Global::isRunningOnBatch())
    {
        Batch currentTask = BatchHeader::getCurrentBatchTask();

        if (currentTask)
        {
            batchJobId = currentTask.BatchJobId;
        }
    }

    dateTimeBegin     = DateTimeUtil::getSystemDateTime();
    updateIntervalSec = logParams.UpdateIntervalSec > 0 ? logParams.UpdateIntervalSec : 5;
    lastDbWrite       = DateTimeUtil::minValue();
    userConnection    = new UserConnection();
    documentCount     = 0;
    lineCount         = 0;

    log.setConnection(userConnection);
    log.initValue();
    log.Operation           = logParams.LogOperation;
    log.StartDateTime       = dateTimeBegin;
    log.Status              = METBatchMonitoringStatus::Running;
    log.LinesToProcess      = totalCount;
    log.UserId              = curuserid();
    log.CompanyId           = curext();
    log.BatchJobId          = batchJobId;
    log.BatchTaskId         = BatchHeader::getCurrentBatchTask().RecId;
    log.setSession();
    log.LastUpdatedDateTime = dateTimeBegin;
    log.IsHeader            = _isHeader;
    log.Details             = description[1];
    log.Details2            = description[2];
    log.Details3            = description[3];
    log.Details4            = description[4];
    log.Details5            = description[5];
    log.Details6            = description[6];
    log.Details7            = description[7];
    log.Details8            = description[8];
    log.Details9            = description[9];
    log.Details10           = description[10];
    log.Details11           = description[11];
    log.Details12           = description[12];

    try
    {
        userConnection.ttsbegin();
        log.insert();
        userConnection.ttscommit();
        logRecId            = log.RecId;
        lastDbWrite         = dateTimeBegin;
        isCommitSuccessful  = true;
    }
    catch
    {

    }
    finally
    {
        if (!isCommitSuccessful)
        {
            userConnection.ttsabort();
        }

        userConnection.finalize();
    }

    return this;
}

public NotesLine parmDescription(NotesLine _description = '')
{
    if (_description)
    {
        description[1] = _description;
    }

    return description[1];
}

public void endTrace(METBatchMonitoringStatus _status = METBatchMonitoringStatus::Completed)
{
    UserConnection  userConnection;
    boolean         isSuccessCommit;

    if (currentLogNotFound)
    {
        return;
    }

    userConnection = new UserConnection();
    log.clear();
    log.setConnection(userConnection);

    try
    {
        userConnection.ttsbegin();

        select forupdate firstonly log
          where log.RecId == logRecId;

        if (log.RecId)
        {
            log.EndDateTime          = DateTimeUtil::getSystemDateTime();
            log.Status               = _status;
            log.DocumentCount        = documentCount;
            log.LineCount            = lineCount;
            log.DualWriteTimeInSec   = round(totalDualWrite[1], 0.01);
            log.LastUpdatedDateTime  = log.EndDateTime;
            log.Duration             = log.durationDisp();
            log.Details              = description[1];
            log.Details2             = description[2];
            log.Details3             = description[3];
            log.Details4             = description[4];
            log.Details5             = description[5];
            log.Details6             = description[6];
            log.Details7             = description[7];
            log.Details8             = description[8];
            log.Details9             = description[9];
            log.Details10            = description[10];
            log.Details11            = description[11];
            log.Details12            = description[12];
            log.Details2Count        = descriptionCount[2];
            log.Details3Count        = descriptionCount[3];
            log.Details4Count        = descriptionCount[4];
            log.Details5Count        = descriptionCount[5];
            log.Details6Count        = descriptionCount[6];
            log.Details7Count        = descriptionCount[7];
            log.Details8Count        = descriptionCount[8];
            log.Details9Count        = descriptionCount[9];
            log.Details10Count       = descriptionCount[10];
            log.Details11Count       = descriptionCount[11];
            log.Details12Count       = descriptionCount[12];
            log.Details2TimeInSec    = round(descriptionTotalTime[2], 0.01);
            log.Details3TimeInSec    = round(descriptionTotalTime[3], 0.01);
            log.Details4TimeInSec    = round(descriptionTotalTime[4], 0.01);
            log.Details5TimeInSec    = round(descriptionTotalTime[5], 0.01);
            log.Details6TimeInSec    = round(descriptionTotalTime[6], 0.01);
            log.Details7TimeInSec    = round(descriptionTotalTime[7], 0.01);
            log.Details8TimeInSec    = round(descriptionTotalTime[8], 0.01);
            log.Details9TimeInSec    = round(descriptionTotalTime[9], 0.01);
            log.Details10TimeInSec   = round(descriptionTotalTime[10], 0.01);
            log.Details11TimeInSec   = round(descriptionTotalTime[11], 0.01);
            log.Details12TimeInSec   = round(descriptionTotalTime[12], 0.01);
            log.DualWriteTime2InSec  = round(totalDualWrite[2], 0.01);
            log.DualWriteTime3InSec  = round(totalDualWrite[3], 0.01);
            log.DualWriteTime4InSec  = round(totalDualWrite[4], 0.01);
            log.DualWriteTime5InSec  = round(totalDualWrite[5], 0.01);
            log.DualWriteTime6InSec  = round(totalDualWrite[6], 0.01);
            log.DualWriteTime7InSec  = round(totalDualWrite[7], 0.01);
            log.DualWriteTime8InSec  = round(totalDualWrite[8], 0.01);
            log.DualWriteTime9InSec  = round(totalDualWrite[9], 0.01);
            log.DualWriteTime10InSec = round(totalDualWrite[10], 0.01);
            log.DualWriteTime11InSec = round(totalDualWrite[11], 0.01);
            log.DualWriteTime12InSec = round(totalDualWrite[12], 0.01);
            log.update();
        }
        else
        {
            currentLogNotFound = true;
        }

        userConnection.ttscommit();
        isTraceEnded    = true;
        isSuccessCommit = true;
    }
    finally
    {
        if (!isSuccessCommit)
        {
            userConnection.ttsabort();
        }

        userConnection.finalize();
    }
}

public void incProcessedCountWithDocument(str _details = '', int _documentCount = 1, int _lineCount = 0)
{
    description[1] = _details;
    this.incProcessedCount(_documentCount, _lineCount);
}

public void incProcessedCount(int _documentCount = 1, int _lineCount = 0)
{
    UtcDateTime     now;
    UserConnection  userConnection;
    boolean         isSuccessCommit;

    if (currentLogNotFound)
    {
        return;
    }

    documentCount += _documentCount;
    lineCount     += _lineCount;

    now = DateTimeUtil::getSystemDateTime();

    if (DateTimeUtil::getDifference(now, lastDbWrite) < updateIntervalSec)
    {
        return;
    }

    userConnection = new UserConnection();
    log.clear();

    try
    {
        log.setConnection(userConnection);
        userConnection.ttsbegin();

        select forupdate firstonly log
          where log.RecId == logRecId;

        if (log.RecId)
        {
            log.DocumentCount       = documentCount;
            log.LineCount           = lineCount;
            log.LastUpdatedDateTime = now;
            log.Details             = description[1];
            log.Duration            = log.durationDisp();
            log.update();
        }
        else
        {
            currentLogNotFound = true;
        }

        lastDbWrite     = now;
        userConnection.ttscommit();
        isSuccessCommit = true;
    }
    catch
    {
        exceptionTextFallThrough();
    }
    finally
    {
        if (!isSuccessCommit)
        {
            userConnection.ttsabort();
        }

        userConnection.finalize();
    }
}

public static METProcMetrics construct(METBatchLogOperation _logOperation)
{
    METBatchMonitoringLogParameters logParams = METBatchMonitoringLogParameters::find(_logOperation);
    METProcMetrics                  procMetrics;

    if (!logParams.RecId || !logParams.IsLogEnabled)
    {
        procMetrics = new METProcMetricsDummy();
    }
    else
    {
        procMetrics = new METProcMetrics();
        procMetrics.parmLogParams(logParams);
    }

    return procMetrics;
}

public void ttsCommitTrace(int _slot = 1)
{
    this.startDualWriteTime(_slot);
    ttscommit;
    this.endDualWriteTime(_slot);
}
